{
  "name": "score classifier",
  "description": "classifies a score as high or low",
  "nodes": [
    { "id": "extract", "type": "transform", "name": "Extract", "config": { "expression": "input.score" } },
    { "id": "cond", "type": "condition", "name": "High?", "config": { "expression": "context.extract >= 0.5" } },
    { "id": "high", "type": "transform", "name": "High", "config": { "expression": "'high'" } },
    { "id": "low", "type": "transform", "name": "Low", "config": { "expression": "'low'" } }
  ],
  "edges": [
    { "id": "e1", "source": "extract", "target": "cond" },
    { "id": "e2", "source": "cond", "target": "high", "branch": "true" },
    { "id": "e3", "source": "cond", "target": "low", "branch": "false" }
  ]
}
